-- A JSON array whose elements the catalog declares (.a.b[] INTEGER) is a list: the list functions
-- and lambdas apply to it. Row 1 holds [5, 6]; the others have no such array.
SELECT
  t.nr
, CASE WHEN CASE WHEN JSON_VALUE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$.type()') = 'array' THEN CAST(MULTISET(SELECT jt.v FROM JSON_TABLE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$[*]' COLUMNS (ord FOR ORDINALITY, v NUMBER PATH '$')) jt ORDER BY jt.ord) AS SYS.ODCINUMBERLIST) END IS NULL THEN NULL ELSE (SELECT COUNT(*) FROM TABLE(CASE WHEN JSON_VALUE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$.type()') = 'array' THEN CAST(MULTISET(SELECT jt.v FROM JSON_TABLE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$[*]' COLUMNS (ord FOR ORDINALITY, v NUMBER PATH '$')) jt ORDER BY jt.ord) AS SYS.ODCINUMBERLIST) END)) END AS "size"
, (SELECT SUM(COLUMN_VALUE) FROM TABLE(CASE WHEN JSON_VALUE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$.type()') = 'array' THEN CAST(MULTISET(SELECT jt.v FROM JSON_TABLE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$[*]' COLUMNS (ord FOR ORDINALITY, v NUMBER PATH '$')) jt ORDER BY jt.ord) AS SYS.ODCINUMBERLIST) END)) AS total
, CASE WHEN CASE WHEN JSON_VALUE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$.type()') = 'array' THEN CAST(MULTISET(SELECT jt.v FROM JSON_TABLE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$[*]' COLUMNS (ord FOR ORDINALITY, v NUMBER PATH '$')) jt ORDER BY jt.ord) AS SYS.ODCINUMBERLIST) END IS NULL THEN NULL ELSE ((SELECT COUNT(*) FROM TABLE(CASE WHEN JSON_VALUE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$.type()') = 'array' THEN CAST(MULTISET(SELECT jt.v FROM JSON_TABLE(CASE WHEN JSON_VALUE(t.doc, '$.type()') = 'object' AND JSON_VALUE(t.doc, '$.a.type()') = 'object' THEN JSON_QUERY(t.doc, '$.a.b' RETURNING JSON) END, '$[*]' COLUMNS (ord FOR ORDINALITY, v NUMBER PATH '$')) jt ORDER BY jt.ord) AS SYS.ODCINUMBERLIST) END) WHERE COLUMN_VALUE = 6) > 0) END AS has_six
FROM
 check_complex t